function session(){return read(K.session,null)}function currentUser(){const s=session();return s?read(K.users,[]).find(u=>u.id===s.userId):null}function isAdmin(){return currentUser()?.role==='ADMIN'}function initials(n=''){return n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function setSession(u){write(K.session,{userId:u.id,at:nowISO()})}function logout(){localStorage.removeItem(K.session);location.hash='#home'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.classList.remove('show'),2300)}
function route(){return location.hash.replace(/^#/,'')||'home'}function go(r){if(location.hash==='#'+r){render()}else location.hash='#'+r}
function requireUser(target){const u=currentUser();if(u&&u.role==='USER')return true;state.pendingRoute=target;sessionStorage.setItem('achaki_return',target);go('login');return false}
function requireAdmin(){if(isAdmin())return true;go('login');return false}
function mobileShell(content,active='home',nav=true){return `<div class="mobile-shell">${content}${nav?bottomNav(active):''}</div>`}
function bottomNav(active){return `<nav class="bottom-nav"><button class="nav-item ${active==='home'?'active':''}" data-go="home">${icon('home')}<span>Início</span></button><button class="nav-item ${active==='lost'?'active':''}" data-protected="lost">${icon('search')}<span>Perdi algo</span></button><button class="nav-item" data-protected="found"><span class="nav-main">${icon('plus','lg')}</span><span>Registrar</span></button><button class="nav-item ${active==='records'?'active':''}" data-protected="records">${icon('list')}<span>Registros</span></button><button class="nav-item ${active==='profile'?'active':''}" data-protected="profile">${icon('user')}<span>Perfil</span></button></nav>`}
function bindCommon(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-protected]').forEach(b=>b.onclick=()=>requireUser(b.dataset.protected)&&go(b.dataset.protected))}
function badge(s,approved=true){if(!approved)return `<span class="badge pending">Aguardando aprovação</span>`;const c=s==='Reservado'?'reserved':s==='Devolvido'?'returned':'open';return `<span class="badge ${c}">${esc(s)}</span>`}
function publicHeader(){const u=currentUser();if(u?.role==='USER')return `<div class="mobile-top"><div class="row"><div class="avatar">${initials(u.name)}</div><div class="user-hello"><b>Olá, ${esc(u.name.split(' ')[0])}</b><span>Encontrou ou perdeu algo hoje?</span></div></div><button class="icon-btn" aria-label="Notificações">${icon('bell')}</button></div>`;return `<div class="mobile-top"><div class="brand-mini"><div class="brand-mark">${icon('box')}</div><div><div class="brand-title">Achados & Perdidos</div><div class="brand-sub">Fatec Taquaritinga</div></div></div><button class="login-pill" data-go="login">Entrar</button></div>`}
function homePage(){const settings=read(K.settings,{});const cats=['Todos',...settings.categories.slice(0,4)];const content=`<section class="mobile-page">${publicHeader()}<div class="search-row"><div class="search-box">${icon('search')}<input id="homeSearch" class="control" placeholder="Buscar por palavra-chave"></div><button id="openFilters" class="filter-square">${icon('filter')}</button></div><div class="quick-grid"><button id="quickFound" class="quick-card red-card"><span class="quick-icon">${icon('plus')}</span><span><b>Encontrei um item</b><small>Registrar achado</small></span></button><button id="quickLost" class="quick-card dark-card"><span class="quick-icon">${icon('search')}</span><span><b>Perdi um item</b><small>Abrir solicitação</small></span></button></div><div class="chips">${cats.map(c=>`<button class="chip ${state.category===c?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="section-head"><h3>Itens encontrados recentemente</h3><a id="showAll">Ver todos</a></div><div id="homeItems" class="item-list"></div></section>`;$('#app').innerHTML=mobileShell(content,'home',true);bindCommon();$('#quickFound').onclick=()=>requireUser('found')&&go('found');$('#quickLost').onclick=()=>requireUser('lost')&&go('lost');$('#openFilters').onclick=openFilters;$('#homeSearch').oninput=renderHomeItems;$$('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;homePage()});renderHomeItems()}
function visibleItems(){const q=norm($('#homeSearch')?.value||'');return read(K.items,[]).filter(i=>i.approved&&i.status!=='Devolvido').filter(i=>{const text=norm(`${i.title} ${i.description} ${i.location} ${i.category}`);const cat=state.category==='Todos'||i.category===state.category;const fc=!state.filters.category||i.category===state.filters.category;const fs=!state.filters.status||i.status===state.filters.status;const fl=!state.filters.location||i.location===state.filters.location;const ff=!state.filters.from||i.date>=state.filters.from;const ft=!state.filters.to||i.date<=state.filters.to;return(!q||text.includes(q))&&cat&&fc&&fs&&fl&&ff&&ft})}
function renderHomeItems(){const el=$('#homeItems');if(!el)return;const arr=visibleItems();el.innerHTML=arr.length?arr.map(i=>`<article class="item-card" data-detail="${i.id}"><div class="item-photo"><img src="${i.photos[0]}" alt="${esc(i.title)}"></div><div><div class="row between"><span class="item-kicker">${esc(i.category)}</span>${badge(i.status)}</div><div class="item-title">${esc(i.title)}</div><div class="item-meta">${icon('pin','sm')} ${esc(i.location)} &nbsp; ${icon('calendar','sm')} ${fmtDate(i.date)}</div></div></article>`).join(''):`<div class="empty">${icon('search')}<div>Nenhum item encontrado com esses filtros.</div></div>`;$$('[data-detail]').forEach(e=>e.onclick=()=>go('detail/'+e.dataset.detail))}
function openFilters(){const s=read(K.settings,{});$('#modal-root').innerHTML=`<div class="filter-backdrop" id="filterBg"><div class="filter-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h3>Filtros</h3><span class="link" id="clearFilter">Limpar tudo</span></div><div class="filter-block"><strong>Categoria</strong><div class="filter-wrap">${['Todas',...s.categories].map(c=>`<button class="chip ${(c==='Todas'&&!state.filters.category)||state.filters.category===c?'active':''}" data-fcat="${c}">${c}</button>`).join('')}</div></div><div class="filter-block"><strong>Status</strong><div class="filter-wrap">${['Em aberto','Reservado','Devolvido'].map(c=>`<button class="chip ${state.filters.status===c?'active':''}" data-fstatus="${c}">${c}</button>`).join('')}</div></div><div class="filter-block"><strong>Período</strong><div class="grid2"><input id="fFrom" type="date" class="control" value="${state.filters.from}"><input id="fTo" type="date" class="control" value="${state.filters.to}"></div></div><div class="field"><label>Local</label><select id="fLocation" class="control"><option value="">Todos os locais</option>${s.locations.map(x=>`<option ${state.filters.location===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="grid2"><button class="btn secondary" id="cancelFilter">Cancelar</button><button class="btn full" id="applyFilter">Aplicar filtros</button></div></div></div>`;$$('[data-fcat]').forEach(b=>b.onclick=()=>{$$('[data-fcat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.filters.category=b.dataset.fcat==='Todas'?null:b.dataset.fcat});$$('[data-fstatus]').forEach(b=>b.onclick=()=>{const was=b.classList.contains('active');$$('[data-fstatus]').forEach(x=>x.classList.remove('active'));state.filters.status=was?null:b.dataset.fstatus;if(!was)b.classList.add('active')});$('#clearFilter').onclick=()=>{state.filters={category:null,status:null,from:'',to:'',location:''};closeModal();renderHomeItems()};$('#cancelFilter').onclick=closeModal;$('#applyFilter').onclick=()=>{state.filters.from=$('#fFrom').value;state.filters.to=$('#fTo').value;state.filters.location=$('#fLocation').value;closeModal();renderHomeItems()};$('#filterBg').onclick=e=>{if(e.target.id==='filterBg')closeModal()}}
function closeModal(){$('#modal-root').innerHTML=''}
function detailPage(id){
  const i=read(K.items,[]).find(x=>x.id===id&&x.approved);
  if(!i)return go('home');
  const creator=read(K.users,[]).find(u=>u.id===i.creatorId);
  const u=currentUser();
  const isCreator=u?.role==='USER'&&u.id===i.creatorId;
  const contactName=i.holder==='FATEC'?'Setor de Achados e Perdidos':creator?.name||'Responsável';
  let actionBlock='';
  if(i.status==='Devolvido'){
    actionBlock=`<div class="contact-box"><div class="return-complete">${icon('check')}<div><b>Item devolvido</b><span>${i.returnInfo?.date?`Devolvido em ${fmtDate(i.returnInfo.date)}`:'A devolução deste item já foi registrada.'}</span></div>${i.returnInfo?`<button class="link-button" id="detailReturnInfo">Ver informações</button>`:''}</div></div>`;
  }else if(isCreator){
    actionBlock=`<div class="contact-box"><div class="contact-head"><div><h3>Gerenciar meu registro</h3><span>Este item foi cadastrado por você.</span></div><span class="secure-chip">Meu item</span></div>${i.holder==='USER'?`<div class="custody-note user-custody">${icon('box')}<div><b>O item está com você</b><span>Quando entregar ao proprietário, registre a devolução para manter o histórico atualizado.</span></div></div><button id="detailDirectReturn" class="btn full return-btn">${icon('check')} Registrar devolução</button>`:`<div class="custody-note">${icon('box')}<div><b>Item entregue à Fatec</b><span>A devolução é registrada pelo administrador responsável pelo setor.</span></div></div>`}</div>`;
  }else if(u?.role==='USER'){
    actionBlock=`<div class="contact-box"><div class="contact-head"><div><h3>Entrar em contato</h3><span>Contato liberado para usuário autenticado.</span></div><span class="secure-chip">${icon('lock','sm')} Protegido</span></div><div class="contact-owner"><div class="avatar">${initials(contactName)}</div><div><b>${esc(contactName)}</b><span>${i.holder==='FATEC'?'Responsável pela guarda do item':'Pessoa que encontrou o item'}</span></div></div><button id="whatsappContact" class="whatsapp-btn">${icon('whatsapp')} Entrar em contato pelo WhatsApp</button></div>`;
  }else{
    actionBlock=`<div class="contact-box"><div class="contact-head"><div><h3>Entrar em contato</h3><span>O contato é protegido por login.</span></div><span class="secure-chip">${icon('lock','sm')} Protegido</span></div><div class="locked-contact-v2"><div class="contact-preview-blur"><div class="contact-owner"><div class="avatar">AP</div><div><b>Responsável pelo item</b><span>Contato disponível após autenticação</span></div></div><div class="whatsapp-btn">${icon('whatsapp')} Entrar em contato pelo WhatsApp</div></div><div class="contact-gate"><div class="lock-circle">${icon('lock')}</div><div><b>Faça login para continuar</b><span>Entre na sua conta para visualizar o responsável e abrir a conversa no WhatsApp.</span></div><button id="loginFromContact" class="btn sm">Entrar</button></div></div></div>`;
  }
  const content=`<section class="mobile-page detail-page"><div class="detail-hero"><img src="${i.photos[0]}" alt="${esc(i.title)}"><div class="detail-actions"><button class="icon-btn" id="detailBack">${icon('back')}</button><button class="icon-btn" id="shareItem">${icon('share')}</button></div></div><div class="row between">${badge(i.status)}<span class="detail-code">Código #${esc(i.id.toUpperCase())}</span></div><h1 class="detail-title">${esc(i.title)}</h1><p class="detail-description">${esc(i.description)}</p><div class="detail-info"><div class="info-row">${icon('box')}<div><span>Categoria</span><b>${esc(i.category)}</b></div></div><div class="info-row">${icon('pin')}<div><span>Local onde foi encontrado</span><b>${esc(i.location)}</b></div></div><div class="info-row">${icon('calendar')}<div><span>Data do encontro</span><b>${fmtDate(i.date)}</b></div></div></div><div class="current-location">${icon('box')}<div><b>Onde o item está agora</b><br>${i.status==='Devolvido'?'Item já devolvido ao proprietário':i.holder==='FATEC'?'Entregue ao setor de Achados e Perdidos da Fatec':'O item permanece com quem o encontrou'}</div></div>${actionBlock}</section>`;
  $('#app').innerHTML=mobileShell(content,'home',false);
  $('#detailBack').onclick=()=>history.length>1?history.back():go('home');
  $('#shareItem').onclick=async()=>{const txt=`${i.title} - encontrado em ${i.location}`;if(navigator.share)try{await navigator.share({title:'Achados & Perdidos',text:txt})}catch{}else{await navigator.clipboard?.writeText(txt);toast('Informações copiadas.')}};
  if($('#loginFromContact'))$('#loginFromContact').onclick=()=>{sessionStorage.setItem('achaki_return','detail/'+i.id);go('login')};
  if($('#whatsappContact'))$('#whatsappContact').onclick=()=>openWhatsapp(i,creator);
  if($('#detailDirectReturn'))$('#detailDirectReturn').onclick=()=>directReturnModal(i.id);
  if($('#detailReturnInfo'))$('#detailReturnInfo').onclick=()=>returnDetailsModal(i.id);
}
function openWhatsapp(i,creator){const s=read(K.settings,{});const phone=i.holder==='FATEC'?s.sectorWhatsApp:creator?.phone;if(!phone)return toast('Contato não configurado.');const msg=`Olá! Vi no sistema Achados & Perdidos da Fatec o item "${i.title}" (código ${i.id}) e gostaria de conversar sobre ele.`;window.open(`https://wa.me/${String(phone).replace(/\D/g,'')}?text=${encodeURIComponent(msg)}`,'_blank','noopener')}
function loginPage(){const returnTo=sessionStorage.getItem('achaki_return');const content=`<section class="mobile-page white no-nav"><div class="auth-titlebar"><button class="icon-btn" id="authBack">${icon('back')}</button><h2>Login</h2><span></span></div><div class="logo-main">${icon('box','lg')}</div><h1 class="auth-h1">Achados & Perdidos</h1><div class="campus">Fatec Taquaritinga</div><p class="subtitle" style="margin-bottom:17px">Entre para registrar itens encontrados ou procurar algo que você perdeu no campus.</p>${returnTo?.startsWith('detail/')?`<div class="notice" style="margin-bottom:11px">Entre na sua conta para visualizar o contato do responsável pelo item.</div>`:''}<div class="field"><label>E-mail</label><input id="loginEmail" class="control" type="email" autocomplete="email" placeholder="seu@email.com"></div><div class="field"><label>Senha</label><input id="loginPass" class="control" type="password" autocomplete="current-password" placeholder="••••••••"></div><div class="row between" style="font-size:9px;margin:-2px 0 13px"><label class="row"><input type="checkbox"> Lembrar de mim</label><span class="link" id="forgotLink">Esqueci minha senha</span></div><button id="doLogin" class="btn full">Entrar</button><div class="auth-footer">Não tem conta? <span class="link" id="registerLink">Cadastre-se</span></div></section>`;$('#app').innerHTML=mobileShell(content,'home',false);$('#authBack').onclick=()=>history.length>1?history.back():go('home');$('#registerLink').onclick=()=>go('register');$('#forgotLink').onclick=()=>go('forgot');$('#doLogin').onclick=doLogin;$('#loginPass').onkeydown=e=>{if(e.key==='Enter')doLogin()}}
async function doLogin(){const email=norm($('#loginEmail').value),ph=await hashPassword($('#loginPass').value);const u=read(K.users,[]).find(x=>norm(x.email)===email&&x.passwordHash===ph);if(!u)return toast('E-mail ou senha inválidos.');if(!u.active)return toast('Este usuário está desativado.');setSession(u);const ret=sessionStorage.getItem('achaki_return');sessionStorage.removeItem('achaki_return');if(u.role==='ADMIN')go('admin-dashboard');else go(ret||'home');toast('Login realizado com sucesso.')}
function registerPage(){const content=`<section class="mobile-page white no-nav"><div class="auth-titlebar"><button class="icon-btn" id="regBack">${icon('back')}</button><h2>Criar conta</h2><span></span></div><p class="subtitle" style="margin-bottom:13px">Preencha seus dados para acessar o sistema de achados e perdidos da Fatec.</p><div class="field"><label>Nome completo</label><input id="rName" class="control"></div><div class="field"><label>E-mail</label><input id="rEmail" class="control" type="email"></div><div class="field"><label>Telefone / WhatsApp</label><input id="rPhone" class="control" placeholder="(16) 99999-9999"></div><div class="field"><label>Senha</label><input id="rPass" class="control" type="password"></div><div class="field"><label>Confirmar senha</label><input id="rConfirm" class="control" type="password"></div><label class="row" style="font-size:9px;align-items:flex-start"><input id="rTerms" type="checkbox"><span>Li e aceito os Termos de uso e a Política de privacidade.</span></label><button id="createUser" class="btn full" style="margin-top:13px">Criar conta</button><div class="auth-footer">Já tem conta? <span class="link" data-go="login">Entrar</span></div></section>`;$('#app').innerHTML=mobileShell(content,'home',false);bindCommon();$('#regBack').onclick=()=>go('login');$('#createUser').onclick=createUser}
async function createUser(){const name=$('#rName').value.trim(),email=$('#rEmail').value.trim().toLowerCase(),phone=$('#rPhone').value.trim(),pass=$('#rPass').value;if(!name||!email||!phone||!pass)return toast('Preencha todos os campos.');if(pass.length<4)return toast('A senha precisa ter pelo menos 4 caracteres.');if(pass!==$('#rConfirm').value)return toast('As senhas não conferem.');if(!$('#rTerms').checked)return toast('Aceite os termos para continuar.');const users=read(K.users,[]);if(users.some(u=>norm(u.email)===norm(email)))return toast('Este e-mail já está cadastrado.');const u={id:'u-'+Date.now(),name,email,passwordHash:await hashPassword(pass),phone:phone.replace(/\D/g,''),role:'USER',course:'Aluno',campus:'Fatec Taquaritinga',active:true};users.push(u);write(K.users,users);setSession(u);go('home');toast('Conta criada com sucesso.')}
function forgotPage(){const content=`<section class="mobile-page white no-nav"><div class="auth-titlebar"><button class="icon-btn" id="forgotBack">${icon('back')}</button><h2>Recuperar senha</h2><span></span></div><div class="logo-main" style="background:#fff0f0;color:var(--red)">${icon('lock','lg')}</div><h2 style="font-size:22px;margin:0 0 5px">Esqueceu sua senha?</h2><p class="subtitle" style="margin-bottom:15px">Informe o e-mail cadastrado para redefinir a senha nesta demonstração.</p><div class="field"><label>E-mail cadastrado</label><input id="fEmail" class="control" type="email"></div><div class="field"><label>Nova senha</label><input id="fPass" class="control" type="password"></div><button id="resetPass" class="btn full">Redefinir senha</button><div class="notice green" style="margin-top:12px">Nesta versão acadêmica, a redefinição é feita localmente no navegador.</div></section>`;$('#app').innerHTML=mobileShell(content,'home',false);$('#forgotBack').onclick=()=>go('login');$('#resetPass').onclick=resetPassword}
async function resetPassword(){const email=norm($('#fEmail').value),users=read(K.users,[]),u=users.find(x=>norm(x.email)===email&&x.role==='USER');if(!u)return toast('E-mail não encontrado.');if($('#fPass').value.length<4)return toast('A nova senha precisa ter pelo menos 4 caracteres.');u.passwordHash=await hashPassword($('#fPass').value);write(K.users,users);go('login');toast('Senha redefinida.')}
function protectedTop(title){return `<div class="auth-titlebar"><button class="icon-btn" data-go="home">${icon('back')}</button><h2>${title}</h2><span></span></div>`}
function foundPage(){
  if(!requireUser('found'))return;
  state.photos=[];
  const s=read(K.settings,{});
  const content=`<section class="mobile-page">${protectedTop('Registrar item encontrado')}<div class="upload-zone"><div class="upload-title"><div><b>Fotos do item</b><div class="tiny muted">Adicione até 3 fotos. A primeira será a capa.</div></div><span id="photoCount" class="tiny muted">0/3</span></div><div id="photoGrid" class="photo-grid"><label class="photo-add">${icon('camera','lg')}<b>Adicionar</b><input id="photoInput" hidden type="file" accept="image/*" multiple></label></div></div><div class="field"><label>Título do item</label><input id="foTitle" class="control" placeholder="Ex.: Fone de ouvido sem fio"></div><div class="field"><label>Descrição</label><textarea id="foDesc" class="control" placeholder="Descreva o item com detalhes"></textarea></div><div class="grid2"><div class="field"><label>Categoria</label><select id="foCat" class="control">${s.categories.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Data do encontro</label><input id="foDate" type="date" class="control" value="${today()}"></div></div><div class="field"><label>Local onde foi encontrado</label><select id="foLocation" class="control"><option value="">Selecione</option>${s.locations.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Onde o item está agora?</label><div class="choice-grid"><button class="choice-card" data-holder="USER"><b>Está comigo</b><span>Quem perdeu poderá combinar a retirada com você.</span></button><button class="choice-card active" data-holder="FATEC"><b>Entreguei na Fatec</b><span>O item está no setor de Achados e Perdidos.</span></button></div></div><div class="field"><label>O item já foi devolvido ao proprietário?</label><div class="choice-grid"><button class="choice-card active" data-found-returned="NO"><b>Ainda não</b><span>O item continua aguardando o proprietário.</span></button><button class="choice-card" data-found-returned="YES"><b>Sim, já foi devolvido</b><span>Registre os dados para manter o histórico.</span></button></div></div><div id="foundReturnFields" class="return-fields hidden"><div class="return-fields-title">${icon('check')} Informações da devolução</div><div class="field"><label>Nome do proprietário</label><input id="foOwner" class="control" placeholder="Nome de quem recebeu o item"></div><div class="grid2"><div class="field"><label>Data da devolução</label><input id="foReturnDate" type="date" class="control" value="${today()}"></div><div class="field"><label>Telefone (opcional)</label><input id="foOwnerPhone" class="control" placeholder="(16) 99999-9999"></div></div><div class="field"><label>Observações (opcional)</label><textarea id="foReturnNotes" class="control" placeholder="Ex.: entregue pessoalmente após confirmação das características"></textarea></div></div><div class="notice">Seu registro será revisado pela administração antes de aparecer para os demais usuários.</div><button id="publishFound" class="btn full" style="margin-top:12px">Publicar registro</button></section>`;
  $('#app').innerHTML=mobileShell(content,'found',true);
  bindCommon();
  $('#photoInput').onchange=e=>handlePhotos(e.target.files);
  $$('[data-holder]').forEach(b=>b.onclick=()=>{$$('[data-holder]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
  $$('[data-found-returned]').forEach(b=>b.onclick=()=>{$$('[data-found-returned]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#foundReturnFields').classList.toggle('hidden',b.dataset.foundReturned!=='YES')});
  $('#publishFound').onclick=saveFound;
}
function compressImage(file,max=720,q=.66){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const sc=Math.min(1,max/Math.max(img.width,img.height)),w=Math.round(img.width*sc),h=Math.round(img.height*sc),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);res(c.toDataURL('image/jpeg',q))};img.onerror=rej;img.src=r.result};r.onerror=rej;r.readAsDataURL(file)})}
function renderPhotoGrid(){const g=$('#photoGrid');g.innerHTML=state.photos.map((p,i)=>`<div class="photo-slot"><img src="${p}"><button class="remove-photo" data-rm="${i}">×</button></div>`).join('')+(state.photos.length<3?`<label class="photo-add">${icon('camera','lg')}<b>Adicionar</b><input id="photoInput2" hidden type="file" accept="image/*" multiple></label>`:'');$('#photoCount').textContent=`${state.photos.length}/3`;$$('[data-rm]').forEach(b=>b.onclick=e=>{e.preventDefault();state.photos.splice(+b.dataset.rm,1);renderPhotoGrid()});if($('#photoInput2'))$('#photoInput2').onchange=e=>handlePhotos(e.target.files)}
function saveFound(){
  if(!state.photos.length)return toast('Adicione pelo menos uma foto.');
  const title=$('#foTitle').value.trim(),desc=$('#foDesc').value.trim(),cat=$('#foCat').value,date=$('#foDate').value,location=$('#foLocation').value,holder=$('[data-holder].active').dataset.holder;
  const returned=$('[data-found-returned].active')?.dataset.foundReturned==='YES';
  if(!title||!desc||!date||!location)return toast('Preencha todos os campos obrigatórios.');
  let returnInfo=null;
  if(returned){
    const ownerName=$('#foOwner').value.trim(),returnDate=$('#foReturnDate').value;
    if(!ownerName||!returnDate)return toast('Informe o proprietário e a data da devolução.');
    returnInfo={ownerName,phone:$('#foOwnerPhone').value.replace(/\D/g,''),document:'',date:returnDate,notes:$('#foReturnNotes').value.trim(),registeredBy:currentUser().id,method:holder==='USER'?'DIRECT_USER':'FINDER_REPORTED'};
  }
  const items=read(K.items,[]);
  if(items.some(i=>norm(i.title)===norm(title)&&i.category===cat&&i.date===date&&i.location===location))return toast('Já existe um registro idêntico.');
  items.unshift({id:'item-'+Date.now(),creatorId:currentUser().id,title,description:desc,category:cat,date,location,holder,status:returned?'Devolvido':'Em aberto',approved:false,photos:[...state.photos],createdAt:nowISO(),returnInfo});
  write(K.items,items);
  go('records');
  toast(returned?'Registro enviado com a devolução informada.':'Registro enviado para aprovação.');
}
function lostPage(){if(!requireUser('lost'))return;const s=read(K.settings,{});const content=`<section class="mobile-page">${protectedTop('Registrar item perdido')}<div class="notice">Descreva o item com o máximo de detalhes. Isso ajuda a equipe a identificar o dono quando ele for encontrado.</div><div class="field" style="margin-top:11px"><label>O que você perdeu?</label><input id="loTitle" class="control" placeholder="Ex.: Garrafa térmica azul"></div><div class="field"><label>Descrição</label><textarea id="loDesc" class="control" placeholder="Cor, marca, adesivos ou qualquer detalhe"></textarea></div><div class="grid2"><div class="field"><label>Categoria</label><select id="loCat" class="control">${s.categories.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Data aproximada</label><input id="loDate" class="control" type="date" value="${today()}"></div></div><div class="field"><label>Onde acha que perdeu? (opcional)</label><select id="loLocation" class="control"><option value="">Selecione um local</option>${s.locations.map(x=>`<option>${x}</option>`).join('')}</select></div><label class="record-card row between"><div><b class="small">Compartilhar meu contato</b><div class="tiny muted">Permite que a equipe fale com você.</div></div><input id="loShare" type="checkbox" checked></label><button id="saveLost" class="btn full">Registrar solicitação</button></section>`;$('#app').innerHTML=mobileShell(content,'lost',true);bindCommon();$('#saveLost').onclick=saveLost}
function saveLost(){const title=$('#loTitle').value.trim(),desc=$('#loDesc').value.trim(),cat=$('#loCat').value,date=$('#loDate').value;if(!title||!desc||!date)return toast('Preencha os campos obrigatórios.');const arr=read(K.lost,[]);arr.unshift({id:'lost-'+Date.now(),userId:currentUser().id,title,description:desc,category:cat,date,location:$('#loLocation').value,shareContact:$('#loShare').checked,status:'Em aberto',createdAt:nowISO()});write(K.lost,arr);go('records');toast('Solicitação registrada.')}
function recordsPage(){
  if(!requireUser('records'))return;
  const u=currentUser(),found=read(K.items,[]).filter(i=>i.creatorId===u.id),lost=read(K.lost,[]).filter(i=>i.userId===u.id);
  let list='';
  if(state.recordTab==='Todos'||state.recordTab==='Encontrei')list+=found.map(recordFound).join('');
  if(state.recordTab==='Todos'||state.recordTab==='Perdi')list+=lost.map(recordLost).join('');
  const content=`<section class="mobile-page"><div class="mobile-top"><h2 style="margin:0;font-size:20px">Meus registros</h2><div class="records-summary">${found.length+lost.length} registro${found.length+lost.length===1?'':'s'}</div></div><div class="tabs">${['Todos','Encontrei','Perdi'].map(t=>`<button class="${state.recordTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div>${list||`<div class="empty">${icon('list')}<div>Você ainda não possui registros nesta categoria.</div></div>`}</div></section>`;
  $('#app').innerHTML=mobileShell(content,'records',true);
  bindCommon();
  $$('[data-tab]').forEach(b=>b.onclick=()=>{state.recordTab=b.dataset.tab;recordsPage()});
  $$('[data-rec-detail]').forEach(b=>b.onclick=()=>go('detail/'+b.dataset.recDetail));
  $$('[data-rate]').forEach(b=>b.onclick=()=>go('rating/'+b.dataset.rate));
  $$('[data-direct-return]').forEach(b=>b.onclick=()=>directReturnModal(b.dataset.directReturn));
  $$('[data-return-details]').forEach(b=>b.onclick=()=>returnDetailsModal(b.dataset.returnDetails));
}
function recordFound(i){
  let management='';
  if(i.status==='Devolvido'){
    management=`<div class="record-status-panel returned-panel">${icon('check')}<div><b>Item devolvido</b><span>${i.returnInfo?.date?`Devolvido em ${fmtDate(i.returnInfo.date)}`:'Devolução registrada'}</span></div>${i.returnInfo?`<button class="mini-action" data-return-details="${i.id}">Ver devolução</button>`:''}</div>`;
  }else if(i.holder==='USER'){
    management=`<div class="record-status-panel"><div class="status-dot red-dot"></div><div><b>O item está com você</b><span>Após entregar ao proprietário, registre a devolução.</span></div><button class="mini-action primary" data-direct-return="${i.id}">Registrar devolução</button></div>`;
  }else{
    management=`<div class="record-status-panel fatec-panel">${icon('box')}<div><b>Sob guarda da Fatec</b><span>A devolução será registrada pelo setor responsável.</span></div></div>`;
  }
  return `<article class="record-card"><div class="record-main"><div class="item-photo"><img src="${i.photos[0]}"></div><div class="grow"><div class="item-kicker">Você encontrou</div><div class="item-title">${esc(i.title)}</div><div class="item-meta">${esc(i.location)} · ${fmtDate(i.date)}</div></div>${badge(i.status,i.approved)}</div><div class="record-footer"><span>${i.approved?'Registro aprovado':'Aguardando aprovação'}</span>${i.approved?`<span class="link" data-rec-detail="${i.id}">Ver detalhes ›</span>`:`<span class="muted">Em análise</span>`}</div>${management}</article>`;
}
function recordLost(i){
  const rated=i.matchedItemId&&read(K.ratings,[]).some(r=>r.itemId===i.matchedItemId&&r.userId===currentUser().id);
  const recovered=i.status==='Devolvido';
  return `<article class="record-card"><div class="record-main"><div class="item-photo" style="display:grid;place-items:center;color:#6e7b90">${icon('search','lg')}</div><div class="grow"><div class="item-kicker">Você perdeu</div><div class="item-title">${esc(i.title)}</div><div class="item-meta">${esc(i.location||'Local não informado')} · ${fmtDate(i.date)}</div></div>${badge(i.status)}</div><div class="record-footer"><span>${i.shareContact?'Contato compartilhado':'Contato privado'}</span>${recovered&&i.matchedItemId&&!rated?`<span class="link" data-rate="${i.matchedItemId}">Avaliar devolução</span>`:recovered?`<span class="muted">Item recuperado</span>`:`<span class="muted">Aguardando localização</span>`}</div>${recovered?`<div class="record-status-panel returned-panel">${icon('check')}<div><b>Item recuperado</b><span>${i.returnDate?`Devolvido em ${fmtDate(i.returnDate)}`:'A devolução foi registrada.'}</span></div></div>`:''}</article>`;
}
function directReturnModal(id){
  const items=read(K.items,[]),i=items.find(x=>x.id===id);
  if(!i||i.creatorId!==currentUser()?.id)return toast('Registro não encontrado.');
  if(i.status==='Devolvido')return returnDetailsModal(id);
  if(i.holder!=='USER')return toast('Como o item está na Fatec, a devolução deve ser registrada pelo administrador.');
  $('#modal-root').innerHTML=`<div class="filter-backdrop" id="directReturnBg"><div class="filter-sheet return-sheet"><div class="sheet-handle"></div><div class="sheet-title"><div><h3>Registrar devolução</h3><span>Informe os dados da entrega ao proprietário.</span></div><button class="icon-btn" id="closeDirectReturn">${icon('x')}</button></div><div class="return-item-summary"><div class="item-photo"><img src="${i.photos[0]}"></div><div><b>${esc(i.title)}</b><span>${esc(i.location)} · encontrado em ${fmtDate(i.date)}</span></div></div><div class="notice green">Use esta opção quando a entrega foi feita diretamente por você ao proprietário.</div><div class="field" style="margin-top:11px"><label>Nome do proprietário</label><input id="drOwner" class="control" placeholder="Nome de quem recebeu o item"></div><div class="grid2"><div class="field"><label>Data da devolução</label><input id="drDate" type="date" class="control" value="${today()}"></div><div class="field"><label>Telefone (opcional)</label><input id="drPhone" class="control" placeholder="(16) 99999-9999"></div></div><div class="field"><label>Observações (opcional)</label><textarea id="drNotes" class="control" placeholder="Ex.: proprietário confirmou as características do item"></textarea></div><label class="confirmation-check"><input id="drConfirm" type="checkbox"><span>Confirmo que o item foi entregue ao proprietário.</span></label><button id="confirmDirectReturn" class="btn full">${icon('check')} Confirmar devolução</button></div></div>`;
  $('#closeDirectReturn').onclick=closeModal;
  $('#directReturnBg').onclick=e=>{if(e.target.id==='directReturnBg')closeModal()};
  $('#confirmDirectReturn').onclick=()=>{
    const owner=$('#drOwner').value.trim(),date=$('#drDate').value;
    if(!owner||!date)return toast('Informe o proprietário e a data da devolução.');
    if(!$('#drConfirm').checked)return toast('Confirme que o item foi entregue.');
    i.status='Devolvido';
    i.returnInfo={ownerName:owner,phone:$('#drPhone').value.replace(/\D/g,''),document:'',date,notes:$('#drNotes').value.trim(),registeredBy:currentUser().id,method:'DIRECT_USER'};
    write(K.items,items);closeModal();recordsPage();toast('Devolução registrada com sucesso.');
  };
}
function returnDetailsModal(id){
  const i=read(K.items,[]).find(x=>x.id===id),r=i?.returnInfo;
  if(!i||!r)return toast('Não há informações de devolução para este item.');
  const method=r.method==='DIRECT_USER'?'Devolução direta':r.method==='FATEC'?'Setor de Achados e Perdidos':r.method==='FINDER_REPORTED'?'Informada pelo registrante':'Registro de devolução';
  $('#modal-root').innerHTML=`<div class="filter-backdrop" id="returnDetailsBg"><div class="filter-sheet return-sheet"><div class="sheet-handle"></div><div class="sheet-title"><div><h3>Informações da devolução</h3><span>Histórico do processo de entrega.</span></div><button class="icon-btn" id="closeReturnDetails">${icon('x')}</button></div><div class="return-success-icon">${icon('check','lg')}</div><h3 class="return-success-title">Item devolvido com sucesso</h3><div class="return-detail-list"><div><span>Item</span><b>${esc(i.title)}</b></div><div><span>Proprietário</span><b>${esc(r.ownerName||'Não informado')}</b></div><div><span>Data da devolução</span><b>${fmtDate(r.date)}</b></div><div><span>Forma de devolução</span><b>${method}</b></div>${r.phone?`<div><span>Telefone informado</span><b>${esc(r.phone)}</b></div>`:''}${r.notes?`<div><span>Observações</span><b>${esc(r.notes)}</b></div>`:''}</div><button class="btn secondary full" id="returnDetailsOk">Fechar</button></div></div>`;
  $('#closeReturnDetails').onclick=$('#returnDetailsOk').onclick=closeModal;
  $('#returnDetailsBg').onclick=e=>{if(e.target.id==='returnDetailsBg')closeModal()};
}
function ratingPage(id){if(!requireUser('records'))return;const i=read(K.items,[]).find(x=>x.id===id);if(!i)return go('records');const content=`<section class="mobile-page no-nav">${protectedTop('Avaliar devolução')}<div class="record-card"><div class="record-main"><div class="item-photo"><img src="${i.photos[0]}"></div><div><div class="item-title">${esc(i.title)}</div><div class="item-meta">Devolvido em ${fmtDate(i.returnInfo?.date||today())}</div></div>${badge('Devolvido')}</div></div><div class="rating-box"><h3>Como foi o processo de devolução?</h3><div class="stars">${[1,2,3,4,5].map(n=>`<button class="star ${n<=state.rating?'active':''}" data-star="${n}">★</button>`).join('')}</div><div class="small red">${['','Muito ruim','Ruim','Bom','Muito bom','Excelente'][state.rating]}</div></div><div class="field" style="margin-top:11px"><label>O que funcionou bem?</label><div class="tag-wrap">${['Atendimento rápido','Fácil de retirar','Comunicação clara','Processo simples'].map(t=>`<button class="tag ${state.ratingTags.has(t)?'active':''}" data-tag="${t}">${t}</button>`).join('')}</div></div><div class="field"><label>Comentário (opcional)</label><textarea id="ratingComment" class="control"></textarea></div><button id="sendRating" class="btn full">Enviar avaliação</button></section>`;$('#app').innerHTML=mobileShell(content,'records',false);bindCommon();$$('[data-star]').forEach(b=>b.onclick=()=>{state.rating=+b.dataset.star;ratingPage(id)});$$('[data-tag]').forEach(b=>b.onclick=()=>{const t=b.dataset.tag;state.ratingTags.has(t)?state.ratingTags.delete(t):state.ratingTags.add(t);b.classList.toggle('active')});$('#sendRating').onclick=()=>{const arr=read(K.ratings,[]);arr.push({id:'rating-'+Date.now(),itemId:id,userId:currentUser().id,score:state.rating,tags:[...state.ratingTags],comment:$('#ratingComment').value.trim(),createdAt:nowISO()});write(K.ratings,arr);state.rating=4;state.ratingTags.clear();go('records');toast('Avaliação enviada. Obrigado!')}}
function profilePage(){if(!requireUser('profile'))return;const u=currentUser(),found=read(K.items,[]).filter(i=>i.creatorId===u.id),lost=read(K.lost,[]).filter(i=>i.userId===u.id);const content=`<section class="mobile-page"><div class="mobile-top"><h2 style="margin:0;font-size:20px">Perfil</h2><button class="icon-btn" id="editProfile">${icon('edit')}</button></div><div class="profile-card"><div class="profile-avatar">${initials(u.name)}</div><div><b>${esc(u.name)}</b><span>${esc(u.email)}</span><span class="red">Aluno · ${esc(u.course)}</span></div></div><div class="stats"><div class="stat"><b>${found.length}</b><span>Encontrados</span></div><div class="stat"><b>${lost.length}</b><span>Perdidos</span></div><div class="stat"><b>${found.filter(i=>i.status==='Devolvido').length}</b><span>Devolvidos</span></div></div><div class="profile-menu"><button id="profileData"><span class="left">${icon('user')} Dados pessoais</span>${icon('chev')}</button><button id="changePassword"><span class="left">${icon('lock')} Alterar senha</span>${icon('chev')}</button><button><span class="left">${icon('bell')} Notificações</span><input type="checkbox" checked></button><button id="myRatings"><span class="left">${icon('star')} Minhas avaliações</span>${icon('chev')}</button><button><span class="left">${icon('settings')} Ajuda e termos de uso</span>${icon('chev')}</button></div><button class="btn secondary full" id="userLogout" style="margin-top:10px;color:var(--red)">${icon('logout')} Sair da conta</button></section>`;$('#app').innerHTML=mobileShell(content,'profile',true);bindCommon();$('#userLogout').onclick=logout;$('#editProfile').onclick=$('#profileData').onclick=editProfileModal;$('#changePassword').onclick=changePasswordModal;$('#myRatings').onclick=()=>toast(`${read(K.ratings,[]).filter(r=>r.userId===u.id).length} avaliação(ões) enviada(s).`)}
function editProfileModal(){const u=currentUser();$('#modal-root').innerHTML=`<div class="filter-backdrop" id="profileBg"><div class="filter-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h3>Dados pessoais</h3><button class="icon-btn" id="closeProfile">${icon('x')}</button></div><div class="field"><label>Nome</label><input id="epName" class="control" value="${esc(u.name)}"></div><div class="field"><label>E-mail</label><input id="epEmail" class="control" value="${esc(u.email)}"></div><div class="field"><label>Telefone / WhatsApp</label><input id="epPhone" class="control" value="${esc(u.phone)}"></div><button id="saveProfile" class="btn full">Salvar alterações</button></div></div>`;$('#closeProfile').onclick=closeModal;$('#saveProfile').onclick=()=>{const users=read(K.users,[]),x=users.find(a=>a.id===u.id);x.name=$('#epName').value.trim()||x.name;x.email=$('#epEmail').value.trim()||x.email;x.phone=$('#epPhone').value.replace(/\D/g,'')||x.phone;write(K.users,users);closeModal();profilePage();toast('Dados atualizados.')}}
function changePasswordModal(){$('#modal-root').innerHTML=`<div class="filter-backdrop"><div class="filter-sheet"><div class="sheet-handle"></div><div class="sheet-title"><h3>Alterar senha</h3><button class="icon-btn" id="closePass">${icon('x')}</button></div><div class="field"><label>Senha atual</label><input id="cpOld" class="control" type="password"></div><div class="field"><label>Nova senha</label><input id="cpNew" class="control" type="password"></div><div class="field"><label>Confirmar nova senha</label><input id="cpConfirm" class="control" type="password"></div><button id="savePass" class="btn full">Alterar senha</button></div></div>`;$('#closePass').onclick=closeModal;$('#savePass').onclick=async()=>{const u=currentUser();if(await hashPassword($('#cpOld').value)!==u.passwordHash)return toast('Senha atual incorreta.');if($('#cpNew').value.length<4)return toast('A nova senha precisa ter pelo menos 4 caracteres.');if($('#cpNew').value!==$('#cpConfirm').value)return toast('As novas senhas não conferem.');const users=read(K.users,[]),x=users.find(a=>a.id===u.id);x.passwordHash=await hashPassword($('#cpNew').value);write(K.users,users);closeModal();toast('Senha alterada.')}}
/* ADMIN */
const ADMIN_MENU=[['admin-dashboard','dashboard','Visão geral'],['admin-found','box','Itens encontrados'],['admin-lost','search','Itens perdidos'],['admin-history','history','Histórico'],['admin-users','users','Usuários'],['admin-settings','settings','Configurações']];
function adminLayout(title,body,active){if(!requireAdmin())return '';const u=currentUser();const menu=ADMIN_MENU.map(([r,ic,t])=>`<button class="${active===r?'active':''}" data-go="${r}">${icon(ic)} ${t}</button>`).join('');return `<div class="admin-app"><aside class="admin-sidebar"><div class="admin-brand"><div class="brand-mark">${icon('box')}</div><div><b>Achados & Perdidos</b><span>Painel administrativo</span></div></div><nav class="admin-menu">${menu}</nav><div class="admin-spacer"></div><div class="admin-profile"><div class="avatar">${initials(u.name)}</div><div><b>${esc(u.name)}</b><span>Administrador</span></div><button class="icon-btn" id="adminLogout">${icon('logout','sm')}</button></div></aside><main class="admin-main"><header class="admin-topbar"><h1>${title}</h1><div class="admin-top-actions"><button class="icon-btn">${icon('bell')}</button></div></header><div class="mobile-admin-bar">${ADMIN_MENU.map(([r,ic,t])=>`<button class="${active===r?'active':''}" data-go="${r}">${t}</button>`).join('')}</div><div class="admin-content">${body}</div></main></div>`}
function bindAdmin(){bindCommon();if($('#adminLogout'))$('#adminLogout').onclick=logout}
function adminDashboard(){const items=read(K.items,[]),lost=read(K.lost,[]),ratings=read(K.ratings,[]),returned=items.filter(i=>i.status==='Devolvido'),pending=items.filter(i=>!i.approved),avg=ratings.length?(ratings.reduce((a,b)=>a+b.score,0)/ratings.length).toFixed(1):'—';const body=`<div class="admin-page-title"><div><h2>Visão geral</h2><p>Acompanhe os principais indicadores do sistema.</p></div><button class="btn sm" id="adminNewItem">${icon('plus')} Novo registro</button></div><div class="metric-grid"><div class="metric"><div class="metric-head"><span>Itens encontrados</span><div class="metric-icon red">${icon('box')}</div></div><strong>${items.length}</strong><small>${items.filter(i=>i.status==='Em aberto').length} em aberto</small></div><div class="metric"><div class="metric-head"><span>Itens perdidos</span><div class="metric-icon blue">${icon('search')}</div></div><strong>${lost.length}</strong><small>${lost.filter(i=>i.status==='Em aberto').length} ativos</small></div><div class="metric"><div class="metric-head"><span>Devoluções</span><div class="metric-icon green">${icon('check')}</div></div><strong>${returned.length}</strong><small>histórico total</small></div><div class="metric"><div class="metric-head"><span>Média de avaliação</span><div class="metric-icon amber">${icon('star')}</div></div><strong>${avg}</strong><small>${ratings.length} avaliações</small></div></div><div class="admin-grid-2"><div class="admin-card"><div class="admin-card-head"><h3>Registros por semana</h3><span class="tiny muted">Últimos 6 períodos</span></div><div class="bar-chart">${[35,52,42,65,58,75].map((h,i)=>`<div class="bar-group"><div class="bar red" style="height:${h}%"></div><div class="bar green" style="height:${Math.max(22,h-18)}%"></div><span class="bar-label">S${i+1}</span></div>`).join('')}</div></div><div class="admin-card"><div class="admin-card-head"><h3>Itens por categoria</h3></div>${categoryAdminList(items)}</div></div><div class="admin-grid-2" style="margin-top:12px"><div class="admin-card"><div class="admin-card-head"><h3>Atividade recente</h3><a data-go="admin-found">Ver todos</a></div><div class="activity-list">${items.slice(0,4).map(i=>`<div class="activity"><div class="activity-dot">${icon('box','sm')}</div><div><b>${esc(i.title)}</b><span>${esc(i.location)} · ${fmtDate(i.date)}</span></div></div>`).join('')}</div></div><div class="admin-card"><div class="admin-card-head"><h3>Pendências de aprovação</h3><a data-go="admin-found">Ver todos (${pending.length})</a></div>${pending.length?pending.slice(0,4).map(i=>`<div class="activity"><div class="activity-dot">${icon('camera','sm')}</div><div class="grow"><b>${esc(i.title)}</b><span>${esc(i.location)}</span></div><button class="btn sm" data-approve="${i.id}">Aprovar</button></div>`).join(''):`<div class="empty" style="padding:18px">Nenhuma pendência.</div>`}</div></div>`;$('#app').innerHTML=adminLayout('Visão geral',body,'admin-dashboard');bindAdmin();$$('[data-approve]').forEach(b=>b.onclick=()=>approveItem(b.dataset.approve,true));$('#adminNewItem').onclick=()=>toast('Use a tela do usuário para criar um novo registro nesta demonstração.')}
function categoryAdminList(items){const cats=read(K.settings,{}).categories||[];return `<div class="category-list">${cats.slice(0,5).map((c,idx)=>{const n=items.filter(i=>i.category===c).length,p=items.length?Math.round(n/items.length*100):0;return `<div class="cat-row"><span>${c}</span><div class="progress-track"><div class="progress-fill" style="width:${p}%;background:${['#4e64d9','#6f53c8','#2d9a63','#de9b34','#c95d5d'][idx]}"></div></div><b>${p}%</b></div>`}).join('')}</div>`}
function adminFound(){const items=read(K.items,[]),q=norm(state.adminSearch);let arr=items.filter(i=>!q||norm(`${i.title} ${i.location} ${i.category}`).includes(q));if(state.adminFoundFilter!=='Todos')arr=arr.filter(i=>state.adminFoundFilter==='Pendentes'?!i.approved:i.status===state.adminFoundFilter);const pending=items.filter(i=>!i.approved).length;const body=`<div class="admin-page-title"><div><h2>Itens encontrados</h2><p>Gerencie os registros encontrados e seus status.</p></div><button class="btn sm">${icon('plus')} Novo registro</button></div><div class="metric-grid"><div class="metric"><span>Total de itens</span><strong>${items.length}</strong></div><div class="metric"><span>Reservados</span><strong>${items.filter(i=>i.status==='Reservado').length}</strong></div><div class="metric"><span>Em aberto</span><strong>${items.filter(i=>i.status==='Em aberto').length}</strong></div><div class="metric"><span>Aguardando aprovação</span><strong>${pending}</strong></div></div><div class="table-tools"><input id="adminFoundSearch" class="control" placeholder="Buscar por item, categoria ou local" value="${esc(state.adminSearch)}"><select id="adminFoundStatus" class="control"><option>Todos</option><option ${state.adminFoundFilter==='Pendentes'?'selected':''}>Pendentes</option><option ${state.adminFoundFilter==='Em aberto'?'selected':''}>Em aberto</option><option ${state.adminFoundFilter==='Reservado'?'selected':''}>Reservado</option><option ${state.adminFoundFilter==='Devolvido'?'selected':''}>Devolvido</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ITEM</th><th>CADASTRADO POR</th><th>LOCAL</th><th>DATA</th><th>POSSE ATUAL</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${arr.map(adminFoundRow).join('')}</tbody></table></div>`;$('#app').innerHTML=adminLayout('Itens encontrados',body,'admin-found');bindAdmin();$('#adminFoundSearch').oninput=e=>{state.adminSearch=e.target.value;adminFound()};$('#adminFoundStatus').onchange=e=>{state.adminFoundFilter=e.target.value;adminFound()};bindFoundAdminActions()}
function adminFoundRow(i){const u=read(K.users,[]).find(x=>x.id===i.creatorId);return `<tr><td><div class="table-item"><div class="table-thumb"><img src="${i.photos[0]}"></div><div><b>${esc(i.title)}</b><span>${esc(i.category)}</span></div></div></td><td>${esc(u?.name||'—')}</td><td>${esc(i.location)}</td><td>${fmtDate(i.date)}</td><td>${i.holder==='FATEC'?'Na Fatec':'Com usuário'}</td><td>${!i.approved?badge(i.status,false):`<select class="status-select ${i.status==='Reservado'?'reserved':i.status==='Devolvido'?'returned':'open'}" data-status="${i.id}"><option ${i.status==='Em aberto'?'selected':''}>Em aberto</option><option ${i.status==='Reservado'?'selected':''}>Reservado</option><option ${i.status==='Devolvido'?'selected':''}>Devolvido</option></select>`}</td><td><div class="table-actions">${!i.approved?`<button title="Aprovar" data-approve="${i.id}">${icon('check','sm')}</button><button title="Rejeitar" data-reject="${i.id}">${icon('x','sm')}</button>`:''}<button title="Editar" data-edit-found="${i.id}">${icon('edit','sm')}</button><button title="Registrar devolução" data-return="${i.id}">${icon('history','sm')}</button><button title="Excluir" data-del-found="${i.id}">${icon('trash','sm')}</button></div></td></tr>`}
function bindFoundAdminActions(){$$('[data-status]').forEach(s=>s.onchange=()=>updateItemStatus(s.dataset.status,s.value));$$('[data-approve]').forEach(b=>b.onclick=()=>approveItem(b.dataset.approve,true));$$('[data-reject]').forEach(b=>b.onclick=()=>approveItem(b.dataset.reject,false));$$('[data-edit-found]').forEach(b=>b.onclick=()=>editFoundModal(b.dataset.editFound));$$('[data-return]').forEach(b=>b.onclick=()=>returnModal(b.dataset.return));$$('[data-del-found]').forEach(b=>b.onclick=()=>deleteFound(b.dataset.delFound))}
function approveItem(id,yes){const a=read(K.items,[]),i=a.find(x=>x.id===id);if(!i)return;if(yes){i.approved=true}else{if(!confirm('Rejeitar e remover este registro?'))return;a.splice(a.indexOf(i),1)}write(K.items,a);toast(yes?'Registro aprovado.':'Registro rejeitado.');route().startsWith('admin-dashboard')?adminDashboard():adminFound()}
function updateItemStatus(id,status){const a=read(K.items,[]),i=a.find(x=>x.id===id);if(!i)return;if(status==='Devolvido'){returnModal(id);return}i.status=status;write(K.items,a);adminFound();toast('Status atualizado.')}
function editFoundModal(id){const a=read(K.items,[]),i=a.find(x=>x.id===id),s=read(K.settings,{});if(!i)return;$('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><h3>Editar registro</h3><button class="icon-btn" id="closeAdminModal">${icon('x')}</button></div><div class="field"><label>Título</label><input id="aeTitle" class="control" value="${esc(i.title)}"></div><div class="field"><label>Descrição</label><textarea id="aeDesc" class="control">${esc(i.description)}</textarea></div><div class="grid2"><div class="field"><label>Categoria</label><select id="aeCat" class="control">${s.categories.map(c=>`<option ${c===i.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Data</label><input id="aeDate" type="date" class="control" value="${i.date}"></div></div><div class="field"><label>Local</label><select id="aeLoc" class="control">${s.locations.map(c=>`<option ${c===i.location?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Posse atual</label><select id="aeHolder" class="control"><option value="FATEC" ${i.holder==='FATEC'?'selected':''}>Na Fatec</option><option value="USER" ${i.holder==='USER'?'selected':''}>Com usuário</option></select></div><div class="row between"><button class="btn secondary" id="closeAdminModal2">Cancelar</button><button class="btn" id="saveAdminEdit">Salvar alterações</button></div></div></div>`;$('#closeAdminModal').onclick=$('#closeAdminModal2').onclick=closeModal;$('#saveAdminEdit').onclick=()=>{i.title=$('#aeTitle').value.trim();i.description=$('#aeDesc').value.trim();i.category=$('#aeCat').value;i.date=$('#aeDate').value;i.location=$('#aeLoc').value;i.holder=$('#aeHolder').value;write(K.items,a);closeModal();adminFound();toast('Registro atualizado.')}}
function returnModal(id){
  const a=read(K.items,[]),i=a.find(x=>x.id===id);if(!i)return;
  const lost=read(K.lost,[]).filter(x=>x.status!=='Devolvido');
  const users=read(K.users,[]);
  $('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><div><h3>Registrar devolução</h3><div class="tiny muted">Registre os dados da entrega do item ao proprietário.</div></div><button class="icon-btn" id="closeReturn">${icon('x')}</button></div><div class="record-card"><b class="small">${esc(i.title)}</b><div class="tiny muted">${esc(i.location)} · ${fmtDate(i.date)}</div></div><div class="field"><label>Vincular a uma solicitação de item perdido (opcional)</label><select id="retLost" class="control"><option value="">Nenhuma solicitação</option>${lost.map(l=>{const u=users.find(x=>x.id===l.userId);return `<option value="${l.id}">${esc(l.title)} — ${esc(u?.name||'Usuário')}</option>`}).join('')}</select></div><div class="grid2"><div class="field"><label>Nome do proprietário</label><input id="retName" class="control"></div><div class="field"><label>Telefone</label><input id="retPhone" class="control"></div></div><div class="grid2"><div class="field"><label>Documento</label><input id="retDoc" class="control" placeholder="RA ou documento"></div><div class="field"><label>Data da devolução</label><input id="retDate" type="date" class="control" value="${today()}"></div></div><div class="field"><label>Observações</label><textarea id="retObs" class="control"></textarea></div><div class="row between"><button class="btn secondary" id="cancelReturn">Cancelar</button><button class="btn" id="confirmReturn">Confirmar devolução</button></div></div></div>`;
  $('#closeReturn').onclick=$('#cancelReturn').onclick=closeModal;
  $('#retLost').onchange=()=>{const l=lost.find(x=>x.id===$('#retLost').value),u=users.find(x=>x.id===l?.userId);if(u){$('#retName').value=u.name;$('#retPhone').value=u.phone||''}};
  $('#confirmReturn').onclick=()=>{
    if(!$('#retName').value.trim()||!$('#retDate').value)return toast('Informe o proprietário e a data.');
    i.status='Devolvido';i.returnInfo={ownerName:$('#retName').value.trim(),phone:$('#retPhone').value.trim(),document:$('#retDoc').value.trim(),date:$('#retDate').value,notes:$('#retObs').value.trim(),registeredBy:currentUser().id,method:'FATEC',linkedLostId:$('#retLost').value||null};
    if($('#retLost').value){const l=lost.find(x=>x.id===$('#retLost').value);if(l){const allLost=read(K.lost,[]),target=allLost.find(x=>x.id===l.id);target.status='Devolvido';target.matchedItemId=i.id;target.returnDate=$('#retDate').value;write(K.lost,allLost)}}
    write(K.items,a);closeModal();adminFound();toast('Devolução registrada.');
  };
}
function deleteFound(id){if(!confirm('Excluir este registro?'))return;write(K.items,read(K.items,[]).filter(i=>i.id!==id));adminFound();toast('Registro excluído.')}
function adminLost(){
  const arr=read(K.lost,[]),users=read(K.users,[]);
  const body=`<div class="admin-page-title"><div><h2>Itens perdidos</h2><p>Solicitações registradas pelos usuários.</p></div><button class="btn secondary sm">${icon('download')} Exportar</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ITEM</th><th>USUÁRIO</th><th>CATEGORIA</th><th>DATA APROX.</th><th>LOCAL</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${arr.map(i=>{const u=users.find(x=>x.id===i.userId);return `<tr><td><div class="table-item"><div class="table-thumb" style="display:grid;place-items:center">${icon('search','sm')}</div><div><b>${esc(i.title)}</b><span>${esc(i.description.slice(0,34))}</span></div></div></td><td>${esc(u?.name||'—')}</td><td>${esc(i.category)}</td><td>${fmtDate(i.date)}</td><td>${esc(i.location||'—')}</td><td>${badge(i.status)}</td><td><div class="table-actions">${i.status!=='Devolvido'?`<button data-recover-lost="${i.id}" title="Registrar recuperação">${icon('check','sm')}</button>`:''}<button data-edit-lost="${i.id}">${icon('edit','sm')}</button><button data-del-lost="${i.id}">${icon('trash','sm')}</button></div></td></tr>`}).join('')}</tbody></table></div>`;
  $('#app').innerHTML=adminLayout('Itens perdidos',body,'admin-lost');bindAdmin();
  $$('[data-del-lost]').forEach(b=>b.onclick=()=>{if(confirm('Excluir esta solicitação?')){write(K.lost,read(K.lost,[]).filter(i=>i.id!==b.dataset.delLost));adminLost();toast('Solicitação excluída.')}});
  $$('[data-edit-lost]').forEach(b=>b.onclick=()=>editLostModal(b.dataset.editLost));
  $$('[data-recover-lost]').forEach(b=>b.onclick=()=>recoverLostModal(b.dataset.recoverLost));
}
function recoverLostModal(id){
  const lost=read(K.lost,[]),request=lost.find(x=>x.id===id);
  if(!request)return;
  const users=read(K.users,[]),owner=users.find(u=>u.id===request.userId);
  const items=read(K.items,[]).filter(i=>i.approved&&i.status!=='Devolvido');
  const ordered=[...items].sort((a,b)=>(a.category===request.category?-1:0)-(b.category===request.category?-1:0));
  $('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><div><h3>Registrar recuperação</h3><div class="tiny muted">Vincule a solicitação a um item encontrado e registre a devolução.</div></div><button class="icon-btn" id="closeRecover">${icon('x')}</button></div><div class="record-card"><b class="small">${esc(request.title)}</b><div class="tiny muted">Solicitado por ${esc(owner?.name||'Usuário')} · ${esc(request.category)}</div></div><div class="field"><label>Item encontrado correspondente</label><select id="recoverItem" class="control"><option value="">Selecione um item</option>${ordered.map(i=>`<option value="${i.id}">${esc(i.title)} — ${esc(i.location)}${i.category===request.category?' • mesma categoria':''}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Data da devolução</label><input id="recoverDate" type="date" class="control" value="${today()}"></div><div class="field"><label>Documento (opcional)</label><input id="recoverDoc" class="control" placeholder="RA ou documento"></div></div><div class="field"><label>Observações</label><textarea id="recoverNotes" class="control" placeholder="Informações relevantes sobre a entrega"></textarea></div><div class="row between"><button class="btn secondary" id="cancelRecover">Cancelar</button><button class="btn" id="confirmRecover">Confirmar devolução</button></div></div></div>`;
  $('#closeRecover').onclick=$('#cancelRecover').onclick=closeModal;
  $('#confirmRecover').onclick=()=>{
    const foundId=$('#recoverItem').value,date=$('#recoverDate').value;
    if(!foundId||!date)return toast('Selecione o item encontrado e informe a data.');
    const allItems=read(K.items,[]),found=allItems.find(i=>i.id===foundId);
    if(!found)return toast('Item encontrado não localizado.');
    found.status='Devolvido';
    found.returnInfo={ownerName:owner?.name||'Proprietário',phone:owner?.phone||'',document:$('#recoverDoc').value.trim(),date,notes:$('#recoverNotes').value.trim(),registeredBy:currentUser().id,method:'FATEC',linkedLostId:request.id};
    request.status='Devolvido';request.matchedItemId=found.id;request.returnDate=date;
    write(K.items,allItems);write(K.lost,lost);closeModal();adminLost();toast('Recuperação e devolução registradas.');
  };
}
function editLostModal(id){const a=read(K.lost,[]),i=a.find(x=>x.id===id);if(!i)return;$('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><h3>Editar item perdido</h3><button class="icon-btn" id="clm">${icon('x')}</button></div><div class="field"><label>Título</label><input id="elTitle" class="control" value="${esc(i.title)}"></div><div class="field"><label>Descrição</label><textarea id="elDesc" class="control">${esc(i.description)}</textarea></div><div class="field"><label>Status</label><select id="elStatus" class="control"><option ${i.status==='Em aberto'?'selected':''}>Em aberto</option><option ${i.status==='Devolvido'?'selected':''}>Devolvido</option></select></div><button class="btn full" id="saveLostEdit">Salvar alterações</button></div></div>`;$('#clm').onclick=closeModal;$('#saveLostEdit').onclick=()=>{i.title=$('#elTitle').value.trim();i.description=$('#elDesc').value.trim();i.status=$('#elStatus').value;write(K.lost,a);closeModal();adminLost();toast('Solicitação atualizada.')}}
function adminHistory(){
  const a=read(K.items,[]),ret=a.filter(i=>i.status==='Devolvido'),ratings=read(K.ratings,[]),avg=ratings.length?(ratings.reduce((s,r)=>s+r.score,0)/ratings.length).toFixed(1):'—';
  const methodLabel=m=>m==='DIRECT_USER'?'Direta pelo usuário':m==='FATEC'?'Setor da Fatec':m==='FINDER_REPORTED'?'Informada no cadastro':'—';
  const body=`<div class="admin-page-title"><div><h2>Histórico de devoluções</h2><p>Itens devolvidos e informações do processo.</p></div><button class="btn secondary sm" onclick="exportHistory()">${icon('download')} Exportar relatório</button></div><div class="metric-grid"><div class="metric"><span>Total devolvido</span><strong>${ret.length}</strong></div><div class="metric"><span>Com avaliação</span><strong>${ratings.length}</strong></div><div class="metric"><span>Média</span><strong>${avg}</strong></div><div class="metric"><span>Não devolvidos</span><strong>${a.filter(i=>i.status!=='Devolvido').length}</strong></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ITEM</th><th>PROPRIETÁRIO</th><th>DATA DEVOLUÇÃO</th><th>FORMA</th><th>LOCAL ORIGINAL</th><th>AVALIAÇÃO</th></tr></thead><tbody>${ret.map(i=>{const r=ratings.filter(x=>x.itemId===i.id).at(-1);return `<tr><td><div class="table-item"><div class="table-thumb"><img src="${i.photos[0]}"></div><b>${esc(i.title)}</b></div></td><td>${esc(i.returnInfo?.ownerName||'—')}</td><td>${fmtDate(i.returnInfo?.date)}</td><td>${methodLabel(i.returnInfo?.method)}</td><td>${esc(i.location)}</td><td>${r?`${'★'.repeat(r.score)} <span class="muted">${r.score}/5</span>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`;
  $('#app').innerHTML=adminLayout('Histórico',body,'admin-history');bindAdmin();
}
function exportHistory(){const data=read(K.items,[]).filter(i=>i.status==='Devolvido');downloadJSON('historico-devolucoes.json',data)}
function adminUsers(){const users=read(K.users,[]),normal=users.filter(u=>u.role==='USER'),admins=users.filter(u=>u.role==='ADMIN');const body=`<div class="admin-page-title"><div><h2>Usuários</h2><p>Gerencie usuários e administradores cadastrados.</p></div><button class="btn sm" id="addAdmin">${icon('plus')} Adicionar administrador</button></div><div class="metric-grid"><div class="metric"><span>Total de usuários</span><strong>${users.length}</strong></div><div class="metric"><span>Usuários comuns</span><strong>${normal.length}</strong></div><div class="metric"><span>Administradores</span><strong>${admins.length}</strong></div><div class="metric"><span>Ativos</span><strong>${users.filter(u=>u.active).length}</strong></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>USUÁRIO</th><th>PERFIL</th><th>TELEFONE</th><th>REGISTROS</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="table-item"><div class="avatar" style="width:30px;height:30px">${initials(u.name)}</div><div><b>${esc(u.name)}</b><span>${esc(u.email)}</span></div></div></td><td>${u.role==='ADMIN'?'Administrador':'Aluno'}</td><td>${esc(u.phone||'—')}</td><td>${read(K.items,[]).filter(i=>i.creatorId===u.id).length+read(K.lost,[]).filter(i=>i.userId===u.id).length}</td><td>${u.active?'<span class="badge returned">Ativo</span>':'<span class="badge rejected">Desativado</span>'}</td><td><div class="table-actions"><button data-toggle-user="${u.id}" ${u.id===currentUser().id?'disabled':''}>${u.active?icon('x','sm'):icon('check','sm')}</button></div></td></tr>`).join('')}</tbody></table></div>`;$('#app').innerHTML=adminLayout('Usuários',body,'admin-users');bindAdmin();$('#addAdmin').onclick=addAdminModal;$$('[data-toggle-user]').forEach(b=>b.onclick=()=>toggleUser(b.dataset.toggleUser))}
function toggleUser(id){const a=read(K.users,[]),u=a.find(x=>x.id===id);if(!u)return;u.active=!u.active;write(K.users,a);adminUsers();toast('Status do usuário atualizado.')}
function addAdminModal(){$('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><h3>Adicionar administrador</h3><button class="icon-btn" id="ca">${icon('x')}</button></div><div class="field"><label>Nome</label><input id="aaName" class="control"></div><div class="field"><label>E-mail</label><input id="aaEmail" class="control"></div><div class="field"><label>Telefone</label><input id="aaPhone" class="control"></div><div class="field"><label>Senha inicial</label><input id="aaPass" type="password" class="control"></div><button id="saveAdmin" class="btn full">Criar administrador</button></div></div>`;$('#ca').onclick=closeModal;$('#saveAdmin').onclick=async()=>{if(!$('#aaName').value.trim()||!$('#aaEmail').value.trim()||$('#aaPass').value.length<4)return toast('Preencha os dados corretamente.');const a=read(K.users,[]);a.push({id:'u-admin-'+Date.now(),name:$('#aaName').value.trim(),email:$('#aaEmail').value.trim(),phone:$('#aaPhone').value.replace(/\D/g,''),passwordHash:await hashPassword($('#aaPass').value),role:'ADMIN',course:'Administração',campus:'Fatec Taquaritinga',active:true});write(K.users,a);closeModal();adminUsers();toast('Administrador criado.')}}
function adminSettings(){const s=read(K.settings,{});const body=`<div class="admin-page-title"><div><h2>Configurações</h2><p>Personalize categorias, locais e contato institucional.</p></div><button class="btn sm" id="saveSettings">Salvar alterações</button></div><div class="settings-grid"><div class="admin-card"><div class="admin-card-head"><h3>Categorias de itens</h3><button class="btn secondary sm" id="addCategory">${icon('plus')} Nova categoria</button></div><div class="pill-list" id="catPills">${s.categories.map(c=>`<span class="config-pill">${esc(c)}</span>`).join('')}</div><div class="admin-card-head" style="margin-top:18px"><h3>Locais do campus</h3><button class="btn secondary sm" id="addLocation">${icon('plus')} Novo local</button></div><div>${s.locations.map(x=>`<div class="setting-row"><div><b>${esc(x)}</b><span>Local disponível nos formulários</span></div><span class="badge returned">Ativo</span></div>`).join('')}</div></div><div><div class="admin-card"><h3>Contato do setor</h3><div class="field" style="margin-top:11px"><label>WhatsApp do Achados e Perdidos</label><input id="sectorPhone" class="control" value="${esc(s.sectorWhatsApp)}"></div><div class="notice">Usado quando o item está sob responsabilidade da Fatec.</div></div><div class="admin-card" style="margin-top:12px"><h3>Dados e demonstração</h3><button class="btn secondary full" id="exportBackup" style="margin-top:10px">${icon('download')} Exportar backup</button><button class="btn secondary full" id="resetDemo" style="margin-top:8px;color:var(--red)">Restaurar dados iniciais</button></div></div></div>`;$('#app').innerHTML=adminLayout('Configurações',body,'admin-settings');bindAdmin();$('#saveSettings').onclick=()=>{s.sectorWhatsApp=$('#sectorPhone').value.replace(/\D/g,'');write(K.settings,s);toast('Configurações salvas.')};$('#addCategory').onclick=()=>{const n=prompt('Nome da nova categoria:');if(n&&!s.categories.includes(n)){s.categories.push(n);write(K.settings,s);adminSettings()}};$('#addLocation').onclick=()=>{const n=prompt('Nome do novo local:');if(n&&!s.locations.includes(n)){s.locations.push(n);write(K.settings,s);adminSettings()}};$('#exportBackup').onclick=()=>downloadJSON('achaki-backup.json',{users:read(K.users,[]),items:read(K.items,[]),lost:read(K.lost,[]),ratings:read(K.ratings,[]),settings:read(K.settings,{})});$('#resetDemo').onclick=async()=>{if(!confirm('Restaurar os dados iniciais?'))return;Object.values(K).forEach(k=>localStorage.removeItem(k));await seed();go('home');toast('Dados restaurados.')}}
function downloadJSON(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){closeModal();const r=route();if(r.startsWith('detail/'))return detailPage(r.split('/')[1]);if(r.startsWith('rating/'))return ratingPage(r.split('/')[1]);if(r==='home')return homePage();if(r==='login')return loginPage();if(r==='register')return registerPage();if(r==='forgot')return forgotPage();if(r==='found')return foundPage();if(r==='lost')return lostPage();if(r==='records')return recordsPage();if(r==='profile')return profilePage();if(r==='admin-dashboard')return adminDashboard();if(r==='admin-found')return adminFound();if(r==='admin-lost')return adminLost();if(r==='admin-history')return adminHistory();if(r==='admin-users')return adminUsers();if(r==='admin-settings')return adminSettings();go('home')}
window.addEventListener('hashchange',render);window.addEventListener('DOMContentLoaded',async()=>{await seed();render()});
